'AC-extraction.normalization.1'; import hashlib; import pytest; from src.extraction.base.normalization_engine import compute_transaction_identity_hash, sanitize_account_last4; pytestmark = pytest.mark.no_db
def test_compute_transaction_identity_hash_stability(): legacy_hash = 'abc123def456'; currency = 'SGD'; custody_scope = 'account:1111-2222'; expected_raw = f'v2|{currency}|{custody_scope}|{legacy_hash}'.encode(); expected_digest = hashlib.sha256(expected_raw).hexdigest(); result = compute_transaction_identity_hash(legacy_hash=legacy_hash, currency='sgd', custody_scope=custody_scope); assert result == expected_digest; _m1_h1 = compute_transaction_identity_hash('hash1', 'SGD', 'account:1'); _m1_h2 = compute_transaction_identity_hash('hash1', 'USD', 'account:1'); _m1_h3 = compute_transaction_identity_hash('hash1', 'SGD', 'account:2'); assert _m1_h1 != _m1_h2; assert _m1_h1 != _m1_h3; assert _m1_h2 != _m1_h3; assert sanitize_account_last4('123-456-7890') == '7890'; assert sanitize_account_last4('ACC*9876') == '9876'; assert sanitize_account_last4('12') == '12'; assert sanitize_account_last4('---') is None; assert sanitize_account_last4(None) is None
